BEGIN;
CREATE TABLE email_login_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),email text NOT NULL,code_hash text NOT NULL,attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 5,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX email_login_codes_lookup_idx ON email_login_codes(tenant_id,email,created_at DESC);
CREATE TABLE refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES tenant_users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,replaced_by uuid REFERENCES refresh_tokens(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),channel text NOT NULL CHECK(channel IN('email','sms','whatsapp')),destination text NOT NULL,template_key text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','sending','sent','failed','cancelled')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE email_login_codes ENABLE ROW LEVEL SECURITY;ALTER TABLE email_login_codes FORCE ROW LEVEL SECURITY;ALTER TABLE refresh_tokens ENABLE ROW LEVEL SECURITY;ALTER TABLE refresh_tokens FORCE ROW LEVEL SECURITY;ALTER TABLE notification_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE notification_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY email_login_codes_isolation ON email_login_codes USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY refresh_tokens_isolation ON refresh_tokens USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY notification_outbox_isolation ON notification_outbox USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
